const WILL_DC = 32;
const DAMAGE = "2d8[void]";                  // tune the vortex's damage here
const HOLDER_TOKEN_ID = "2ukQ7Yrj5bLzqL7J"; // placeholder anchor that carried the aura — skip it

if (game.user !== game.users.activeGM) return; // GM posts the card once for everyone

const token = event?.data?.token;
const actor = token?.actor;
if (!actor?.isOfType?.("creature")) return;
if (token.id === HOLDER_TOKEN_ID) return;

// Shadow creatures are immune to the Vortex of Souls.
if (actor.traits?.has?.("shadow")) return;

// At most once per creature per combat round (enter + turn-start must not double up).
const combat = game.combat;
if (combat) {
  const stamp = combat.id + ":" + combat.round;
  if (actor.getFlag("world", "vortexOfSoulsStamp") === stamp) return;
  await actor.setFlag("world", "vortexOfSoulsStamp", stamp);
}

// Negative-healing creatures (undead, dhampirs, …) are healed by the void and ignore the slow.
const healed = !!actor.system?.attributes?.hp?.negativeHealing;
const dmg = "@Damage[" + DAMAGE + "]";
const content = healed
  ? "<strong>" + token.name + "</strong> is bathed in the <strong>Vortex of Souls</strong> and is <em>healed</em> by the void energy: " + dmg + " <em>(immune to the slow)</em>."
  : "<strong>" + token.name + "</strong> is caught in the <strong>Vortex of Souls</strong>: takes " + dmg + " and must succeed at a @Check[will|dc:" + WILL_DC + "] save or become <strong>Slowed 1</strong> (<strong>Slowed 2</strong> on a critical failure).";

await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ token }), content });

